CREATE TABLE IF NOT EXISTS accounting_periods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_accounting_period_dates(start_date,end_date),INDEX idx_accounting_period_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chart_of_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,type ENUM('asset','liability','equity','income','expense') NOT NULL,parent_id BIGINT UNSIGNED NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_coa_type(type),CONSTRAINT fk_coa_parent FOREIGN KEY(parent_id) REFERENCES chart_of_accounts(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_number VARCHAR(40) NOT NULL UNIQUE,client_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,account_id BIGINT UNSIGNED NULL,vendor_name VARCHAR(180) NULL,category VARCHAR(120) NOT NULL,description VARCHAR(500) NULL,amount DECIMAL(15,2) NOT NULL,currency VARCHAR(10) NOT NULL DEFAULT 'USD',expense_date DATE NOT NULL,status ENUM('recorded','voided') NOT NULL DEFAULT 'recorded',receipt_path VARCHAR(500) NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_expense_client(client_id),INDEX idx_expense_project(project_id),INDEX idx_expense_date(expense_date),CONSTRAINT fk_expense_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL,CONSTRAINT fk_expense_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE SET NULL,CONSTRAINT fk_expense_account FOREIGN KEY(account_id) REFERENCES chart_of_accounts(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS financial_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,period_id BIGINT UNSIGNED NULL,account_id BIGINT UNSIGNED NOT NULL,transaction_type ENUM('debit','credit') NOT NULL,amount DECIMAL(15,2) NOT NULL,currency VARCHAR(10) NOT NULL DEFAULT 'USD',reference_type VARCHAR(60) NULL,reference_id BIGINT UNSIGNED NULL,description VARCHAR(500) NULL,transaction_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_ft_account_date(account_id,transaction_date),INDEX idx_ft_reference(reference_type,reference_id),CONSTRAINT fk_ft_period FOREIGN KEY(period_id) REFERENCES accounting_periods(id) ON DELETE SET NULL,CONSTRAINT fk_ft_account FOREIGN KEY(account_id) REFERENCES chart_of_accounts(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_reconciliations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,expected_amount DECIMAL(15,2) NOT NULL,actual_amount DECIMAL(15,2) NOT NULL,difference DECIMAL(15,2) NOT NULL DEFAULT 0,status ENUM('matched','partial','overpaid','underpaid','exception') NOT NULL DEFAULT 'matched',notes TEXT NULL,reconciled_by BIGINT UNSIGNED NULL,reconciled_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_payment_reconciliation(payment_id),INDEX idx_reconciliation_invoice(invoice_id),CONSTRAINT fk_recon_payment FOREIGN KEY(payment_id) REFERENCES invoice_payments(id) ON DELETE CASCADE,CONSTRAINT fk_recon_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO chart_of_accounts(code,name,type) VALUES ('1000','Cash / Bank','asset'),('1100','Accounts Receivable','asset'),('2000','Accounts Payable','liability'),('3000','Owner Equity','equity'),('4000','Service Revenue','income'),('5000','Operating Expenses','expense');